class NobleHTTPClient:
    def __init__(self):
        self.client = NobleTLSClient(
            proxies=[os.getenv("PROXY_URL")] if os.getenv("PROXY_URL") else [],
            client_identifier=noble_tls.Client.CHROME_120,
            random_tls_extension_order=True,
            max_retries=3,
            backoff_base=0.5,
            backoff_factor=2.0,
            max_backoff=60.0,
        )
        logger.debug("Initialized NobleHTTPClient.")

    async def search_listings(self, search_params: list) -> list:
        logger.info(f"Searching listings with params: {search_params}")
        payload = {
            "operationName": "GetModularFeed",
            "variables": {"debug": False, "searchParams": search_params},
            "query": SEARCH_QUERY_STR,
        }
        async with GLOBAL_SEMAPHORE:
            response = await self.client.post(
                "https://client-graphql.offerup.com/",
                headers={**OFFERUP_HEADERS,
                         "x-ou-operation-name": "GetModularFeed",
                         "x-ou-screen": "Items"},
                json_data=payload,
            )
        data = json.loads(response.text)
        listings = self._parse_feed_response(data)
        logger.info(f"Found {len(listings)} listings.")
        return listings

    async def fetch_item_details(self, listing_id: str) -> dict:
        logger.info(f"Fetching details for listing: {listing_id}")
        payload = {
            "operationName": "GetItemDetailDataByListingId",
            "variables": {"listingId": listing_id},
            "query": ITEM_DETAIL_QUERY_STR,
        }
        async with GLOBAL_SEMAPHORE:
            response = await self.client.post(
                "https://client-graphql.offerup.com/",
                headers={**OFFERUP_HEADERS,
                         "x-ou-operation-name": "GetItemDetailDataByListingId",
                         "x-ou-screen": "ItemDetail"},
                json_data=payload,
            )
        data = json.loads(response.text)
        details = data.get("data", {}).get("listing")
        logger.debug(f"Fetched details: {details}")
        return details

    def _parse_feed_response(self, data: dict) -> list:
        feed = data.get("data", {}).get("modularFeed", {})
        listings = []
        loose_tiles = feed.get("looseTiles", [])
        for tile in loose_tiles:
            if tile.get("tileType") == "LISTING":
                listings.append(tile.get("listing", {}))
        for mod in feed.get("modules", []):
            grid = mod.get("grid", {})
            for t in grid.get("tiles", []):
                if t.get("tileType") == "LISTING":
                    listings.append(t.get("listing", {}))
        return listings
